  await page.clock.runFor(1);
  await expect(page.locator('.card.closed')).toHaveCount(16);
  const restored = await exportedSnapshot(page);
  expect(restored).toMatchObject({
    boardCode: EXAMPLE_CODE,
    moves: 1,
    started: true,
    elapsedMs: 800,
    selection: { kind: 'closed' },
  });
});

